package br.edu.utfpr.cantina.view;
import br.edu.utfpr.cantina.controller.ProdutoController;import br.edu.utfpr.cantina.model.Produto;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.math.BigDecimal;import java.sql.SQLException;
public class TelaProdutos extends JPanel{
 private final ProdutoController c;private final JTextField nome=new JTextField(18),preco=new JTextField(8),estoque=new JTextField(6);private int id;private final DefaultTableModel m=new DefaultTableModel(new Object[]{"ID","Produto","Preço","Estoque"},0){public boolean isCellEditable(int r,int col){return false;}};private final JTable t=new JTable(m);private final JLabel alertaEstoque=new JLabel("Alerta de estoque: produtos com 5 unidades ou menos ficam destacados.");
 public TelaProdutos(ProdutoController c){this.c=c;setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(16,16,16,16));JPanel f=new JPanel(new FlowLayout(FlowLayout.LEFT));f.add(new JLabel("Produto"));f.add(nome);f.add(new JLabel("Preço (R$)"));f.add(preco);f.add(new JLabel("Estoque"));f.add(estoque);JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton novo=new JButton("Novo/Limpar"),salvar=new JButton("Salvar"),excluir=new JButton("Excluir"),atualizar=new JButton("Atualizar");for(JButton x:new JButton[]{novo,salvar,excluir,atualizar})b.add(x);JPanel top=new JPanel(new BorderLayout());top.add(new JLabel("Cadastro e controle de produtos"),BorderLayout.NORTH);top.add(f);top.add(b,BorderLayout.SOUTH);top.add(alertaEstoque,BorderLayout.WEST);add(top,BorderLayout.NORTH);t.setRowHeight(27);t.setDefaultRenderer(Object.class,new javax.swing.table.DefaultTableCellRenderer(){@Override public Component getTableCellRendererComponent(JTable table,Object value,boolean selected,boolean focus,int row,int column){Component c=super.getTableCellRendererComponent(table,value,selected,focus,row,column);int qtd=((Number)m.getValueAt(row,3)).intValue();if(!selected){c.setBackground(qtd<=5?new Color(255,239,220):Color.WHITE);c.setForeground(qtd<=5?new Color(150,75,20):new Color(45,55,72));}return c;}});alertaEstoque.setForeground(new Color(165,91,25));add(new JScrollPane(t));novo.addActionListener(e->limpar());salvar.addActionListener(e->salvar());excluir.addActionListener(e->excluir());atualizar.addActionListener(e->carregar());t.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&t.getSelectedRow()>=0){int r=t.getSelectedRow();id=(int)m.getValueAt(r,0);nome.setText((String)m.getValueAt(r,1));preco.setText(m.getValueAt(r,2).toString());estoque.setText(m.getValueAt(r,3).toString());}});carregar();}
 private void carregar(){try{m.setRowCount(0);int baixos=0;for(Produto p:c.listar()){m.addRow(new Object[]{p.getIdProduto(),p.getNome(),p.getPreco(),p.getQuantidadeEstoque()});if(p.getQuantidadeEstoque()<=5)baixos++;}alertaEstoque.setText(baixos==0?"Estoque saudável: nenhum produto com 5 unidades ou menos.":"ATENÇÃO: "+baixos+" produto(s) com estoque baixo (5 unidades ou menos).");}catch(SQLException e){erro(e);}}
 private void salvar(){try{String v=preco.getText().trim().replace(',','.');Produto p=new Produto(id,nome.getText(),new BigDecimal(v),Integer.parseInt(estoque.getText().trim()));c.salvar(p);JOptionPane.showMessageDialog(this,"Produto salvo com sucesso.");limpar();carregar();}catch(NumberFormatException e){JOptionPane.showMessageDialog(this,"Preço e estoque devem ser números válidos.","Dados inválidos",JOptionPane.WARNING_MESSAGE);}catch(IllegalArgumentException e){JOptionPane.showMessageDialog(this,e.getMessage(),"Dados inválidos",JOptionPane.WARNING_MESSAGE);}catch(SQLException e){erro(e);}}
 private void excluir(){if(id==0){JOptionPane.showMessageDialog(this,"Selecione um produto.");return;}if(JOptionPane.showConfirmDialog(this,"Excluir o produto selecionado?","Confirmar",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{c.excluir(id);limpar();carregar();}catch(SQLException e){JOptionPane.showMessageDialog(this,"Não é possível excluir produto vinculado a pedido.\n"+e.getMessage(),"Falha",JOptionPane.WARNING_MESSAGE);}}
 private void limpar(){id=0;nome.setText("");preco.setText("");estoque.setText("");t.clearSelection();}private void erro(SQLException e){JOptionPane.showMessageDialog(this,"Falha ao acessar o banco: "+e.getMessage(),"Erro",JOptionPane.ERROR_MESSAGE);}
}
